import{_ as e,o as d,c as r,a4 as o}from"./chunks/framework.CQGI5ZO3.js";const u=JSON.parse('{"title":"xs-status(7)","description":"Current capabilities and remaining work, generated from the project backlog.","frontmatter":{"title":"xs-status(7)","description":"Current capabilities and remaining work, generated from the project backlog.","manual":"xs-status(7)","manualName":"Development status","sectionNumber":"7"},"headers":[],"relativePath":"development.md","filePath":"development.md"}'),a={name:"development.md"};function s(i,t,n,c,l,p){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="xs-status-7" tabindex="-1">xs-status(7) <a class="header-anchor" href="#xs-status-7" aria-label="Permalink to &quot;xs-status(7)&quot;">​</a></h1><div class="manual-deck"><strong>Development status</strong><p>Current capabilities and remaining work, generated from the project backlog.</p></div><h2 id="scope" tabindex="-1">SCOPE <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;SCOPE {#scope}&quot;">​</a></h2><p>Tier status and open items below are generated from the tier tables in <code>backlog.md</code> on every build. Curated text was last reviewed on 2026-10-10 against the README and executable help. Earlier backlog problem statements are historical; each item’s latest status describes the implemented CLI.</p><aside class="manual-note"><span>NOTE</span><p>This page describes development status. Planned capabilities are not part of the command reference.</p></aside><h2 id="tiers" tabindex="-1">TIER STATUS <a class="header-anchor" href="#tiers" aria-label="Permalink to &quot;TIER STATUS {#tiers}&quot;">​</a></h2><div class="manual-table-wrap"><table><thead><tr><th scope="col">Tier</th><th scope="col">Items</th><th scope="col">Done</th><th scope="col">Closed</th><th scope="col">Open</th></tr></thead><tbody><tr><td>P0 · Trust: things that are wrong or dangerous today</td><td>15</td><td>15</td><td>0</td><td>0</td></tr><tr><td>P1 · Reach: being able to use it against the machines you sync with</td><td>9</td><td>8</td><td>0</td><td>1</td></tr><tr><td>P1 · Everyday behaviour: the flags in your muscle memory</td><td>13</td><td>13</td><td>0</td><td>0</td></tr><tr><td>P2 · Progress and feel: the reason to switch</td><td>11</td><td>10</td><td>1</td><td>0</td></tr><tr><td>P3 · Performance: holding the lead where you actually sync</td><td>14</td><td>0</td><td>0</td><td>14</td></tr><tr><td>P4 · Engineering base</td><td>13</td><td>0</td><td>0</td><td>13</td></tr></tbody></table></div><p>“Closed” items were set aside without completion, for example at the user’s request. Statuses use the backlog’s own vocabulary: <code>partial</code>, <code>new</code>, <code>code</code>, <code>confirmed</code> and <code>unverified</code>.</p><h2 id="implemented" tabindex="-1">IMPLEMENTED CAPABILITIES <a class="header-anchor" href="#implemented" aria-label="Permalink to &quot;IMPLEMENTED CAPABILITIES {#implemented}&quot;">​</a></h2><div class="manual-table-wrap"><table><thead><tr><th scope="col">Area</th><th scope="col">Capabilities</th></tr></thead><tbody><tr><td>Data reuse</td><td>Verified-prefix resume, large-file delta, sparse output, and link-dest snapshots</td></tr><tr><td>Metadata</td><td>Hard links, xattrs, ACLs, incoming mode/owner overrides, platform-specific times and flags</td></tr><tr><td>Automation</td><td>Itemization, formatted stdout, error summaries, JSON progress, bandwidth limits, idle timeouts</td></tr></tbody></table></div><h2 id="open" tabindex="-1">OPEN ITEMS <a class="header-anchor" href="#open" aria-label="Permalink to &quot;OPEN ITEMS {#open}&quot;">​</a></h2><div class="manual-table-wrap"><table><thead><tr><th scope="col">Tier</th><th scope="col">ID</th><th scope="col">Item</th><th scope="col">Status</th></tr></thead><tbody><tr><td>P1</td><td><code>R-01</code></td><td>Real ssh, end to end</td><td>partial</td></tr><tr><td>P3</td><td><code>F-01</code></td><td>Benchmark the real targets</td><td>partial</td></tr><tr><td>P3</td><td><code>F-02</code></td><td>Regression gate</td><td>partial</td></tr><tr><td>P3</td><td><code>F-03</code></td><td>ssh is one stream on one core</td><td>unverified</td></tr><tr><td>P3</td><td><code>F-04</code></td><td>Adaptive compression</td><td>code</td></tr><tr><td>P3</td><td><code>F-05</code></td><td>Large files</td><td>code</td></tr><tr><td>P3</td><td><code>F-06</code></td><td>Linux scan path</td><td>code</td></tr><tr><td>P3</td><td><code>F-07</code></td><td>APFS byte-copy ceiling</td><td>confirmed</td></tr><tr><td>P3</td><td><code>F-08</code></td><td>No-op re-sync burns CPU</td><td>confirmed</td></tr><tr><td>P3</td><td><code>F-09</code></td><td>Memory on very large trees</td><td>code</td></tr><tr><td>P3</td><td><code>F-10</code></td><td>Whole-subtree clones</td><td>new</td></tr><tr><td>P3</td><td><code>F-11</code></td><td>Clones when <code>-a</code> is incomplete</td><td>code</td></tr><tr><td>P3</td><td><code>F-12</code></td><td>Deletion is single-threaded</td><td>code</td></tr><tr><td>P3</td><td><code>F-13</code></td><td>Tiny transfers</td><td>unverified</td></tr><tr><td>P3</td><td><code>F-14</code></td><td><code>-c</code> at scale</td><td>unverified</td></tr><tr><td>P4</td><td><code>Q-01</code></td><td>Version control</td><td>confirmed</td></tr><tr><td>P4</td><td><code>Q-02</code></td><td>CI</td><td>new</td></tr><tr><td>P4</td><td><code>Q-03</code></td><td>difftest on Linux</td><td>confirmed</td></tr><tr><td>P4</td><td><code>Q-04</code></td><td>Sanitizers</td><td>new</td></tr><tr><td>P4</td><td><code>Q-05</code></td><td>Fuzz the wire decoders</td><td>new</td></tr><tr><td>P4</td><td><code>Q-06</code></td><td>Two-machine test rig</td><td>new</td></tr><tr><td>P4</td><td><code>Q-07</code></td><td>Kill and converge</td><td>new</td></tr><tr><td>P4</td><td><code>Q-08</code></td><td>Randomised differential testing</td><td>new</td></tr><tr><td>P4</td><td><code>Q-09</code></td><td>Large and sparse files</td><td>unverified</td></tr><tr><td>P4</td><td><code>Q-10</code></td><td>Option parser versus popt</td><td>code</td></tr><tr><td>P4</td><td><code>Q-11</code></td><td>Progress rendering tests</td><td>new</td></tr><tr><td>P4</td><td><code>Q-12</code></td><td>Internal cleanups</td><td>code</td></tr><tr><td>P4</td><td><code>Q-13</code></td><td>Docs</td><td>new</td></tr></tbody></table></div><p>The product page recordings are real local executions. They do not establish completion of remaining physical-host or native terminal acceptance checks. Historical benchmark speedups predate trust fixes and the atomic-write default.</p><h2 id="gui" tabindex="-1">GUI ENGINE ROADMAP <a class="header-anchor" href="#gui" aria-label="Permalink to &quot;GUI ENGINE ROADMAP {#gui}&quot;">​</a></h2><aside class="manual-note"><span>EXTERNAL</span><p>This roadmap comes from a GUI backlog maintained outside this repository. It is not checked by this build; statuses are as of the 10 October 2026 review.</p></aside><p>All GUI backlog stories G-01–G-24 are open. Existing copy, listing, selection, metadata, and progress primitives are foundations for these requirements, rather than evidence that the full GUI contract exists.</p><div class="manual-table-wrap"><table><thead><tr><th scope="col">Priority</th><th scope="col">Proposed work</th></tr></thead><tbody><tr><td>P0 · G-01–G-08</td><td>Versioned machine interface, deterministic execution, structured browsing, authoritative completion, typed per-item errors, headless SSH auth, conflict decisions, job cancellation</td></tr><tr><td>P1 · G-09–G-18</td><td>Rename/move/delete workflows, private partials, persistent queue/recovery, previews, responsive browsing, preflight/refresh, aggregate controls, helper lifecycle, acceptance client</td></tr><tr><td>P2 · G-19–G-24</td><td>Remote-to-remote copies, additional endpoint adapters, Windows support, large-directory budgets, preview/edit, optional embedded library</td></tr></tbody></table></div><h2 id="boundaries" tabindex="-1">CURRENT BOUNDARIES <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;CURRENT BOUNDARIES {#boundaries}&quot;">​</a></h2><p>Two-pane browsing does not imply automatic bidirectional synchronization. Persistent queues, interactive conflict choices, job-control APIs, and runtime aggregate limits remain proposed GUI integration work. Current <code>--progress=json</code> is documented on the <a href="progress.html#json">output page</a>; it is not a promise of that future versioned GUI API.</p><h2 id="sources" tabindex="-1">MAINTENANCE <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;MAINTENANCE {#sources}&quot;">​</a></h2><p>The option reference and downloadable manpage are generated from <code>xs --help</code>. Exit codes come from the <code>RERR_*</code> definitions in the source, and tier status from <code>backlog.md</code>. Workflow pages are curated from README behavior.</p><p>Source fingerprints for the curated pages are in <a href="sources.json">sources.json</a>; <code>npm run check</code> fails when a fingerprinted source has changed since review.</p>',22)])])}const m=e(a,[["render",s]]);export{u as __pageData,m as default};
